import sys

def restore_binary_string(n0, n1, n2):
    # Start with an empty string
    s = ""

    # Add pairs for n2 (both characters are '1')
    for _ in range(n2):
        s += "11"

    # Add pairs for n1 (one character is '1', one is '0')
    for _ in range(n1):
        if s and s[-1] == '1':
            s += "0"
        else:
            s += "10"

    # Add pairs for n0 (both characters are '0')
    for _ in range(n0):
        s += "00"

    # Ensure the string has at least one '0' and one '1'
    if '0' not in s:
        s += "0"
    if '1' not in s:
        s += "1"

    return s

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n0 = int(data[index])
        n1 = int(data[index + 1])
        n2 = int(data[index + 2])
        index += 3
        results.append(restore_binary_string(n0, n1, n2))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
